From cd0a430ad24d1144864adcd43357008706430383 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 17:06:37 +0100
Subject: [PATCH] greeter: set the resize mode before loading the lock screen

The default mode resized the view to the lock screen's 800x600 implicit
size, so the wallpaper was first decoded at that size and again once the
screen size came back, delaying it after locking. Set it before loading.

CCBUG: 520995
---
 greeter/greeterapp.cpp | 2 +-
 1 file changed, 1 insertion(+), 1 deletion(-)

diff --git a/greeter/greeterapp.cpp b/greeter/greeterapp.cpp
index ec4283b1..075fcd5f 100644
--- a/greeter/greeterapp.cpp
+++ b/greeter/greeterapp.cpp
@@ -360,6 +360,7 @@ QQuickView *UnlockApp::createViewForScreen(QScreen *screen)
     auto wallpaperItem = loadWallpaperPlugin(view, view->width(), view->height(), config);
     view->rootContext()->setContextProperty(QStringLiteral("wallpaper"), wallpaperItem);

+    view->setResizeMode(QQuickView::SizeRootObjectToView);
     view->setSource(m_mainQmlPath);
     // on error, load the fallback lockscreen to not lock the user out of the system
     if (view->status() != QQuickView::Ready) {
@@ -381,7 +382,6 @@ QQuickView *UnlockApp::createViewForScreen(QScreen *screen)
             std::terminate();
         }
     }
-    view->setResizeMode(QQuickView::SizeRootObjectToView);

     if (wallpaperItem) {
         // we need to set this wallpaper properties separately after the lockscreen QML is loaded
-- 
2.53.0

From 0c374f297f6e5fbda393277f7f9907220fcfc882 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 17:04:31 +0100
Subject: [PATCH] lockscreen: fade in once the wallpaper has loaded

The lock screen started its fade-in as soon as it was created, so the
clock faded in on a black screen while the wallpaper was still loading.
Start the fade once the wallpaper has loaded, or after a second at most.

CCBUG: 520995
---
 .../contents/lockscreen/LockScreenUi.qml      | 30 ++++++++++++++++++-
 1 file changed, 29 insertions(+), 1 deletion(-)

diff --git a/desktoppackage/contents/lockscreen/LockScreenUi.qml b/desktoppackage/contents/lockscreen/LockScreenUi.qml
index 065a33c131..8a4f644f13 100644
--- a/desktoppackage/contents/lockscreen/LockScreenUi.qml
+++ b/desktoppackage/contents/lockscreen/LockScreenUi.qml
@@ -141,11 +141,13 @@ Item {
         property bool uiVisible: false
         property bool seenPositionChange: false
         property bool blockUI: containsMouse && (mainStack.depth > 1 || mainBlock.mainPasswordBox.text.length > 0 || Keyboards.KWinVirtualKeyboard.visible)
+        readonly property bool wallpaperLoaded: !wallpaper || !wallpaper.loading

         x: parent.x
         y: parent.y
         width: parent.width
         height: parent.height
+        opacity: 0
         hoverEnabled: true
         cursorShape: uiVisible ? Qt.ArrowCursor : Qt.BlankCursor
         drag.filterChildren: true
@@ -232,7 +234,33 @@ Item {
             duration: Kirigami.Units.veryLongDuration * 2
         }

-        Component.onCompleted: launchAnimation.start();
+        // Don't keep the UI hidden if the wallpaper never reports that it has loaded
+        Timer {
+            id: launchFallbackTimer
+            interval: 1000
+            onTriggered: lockScreenRoot.startLaunchAnimation()
+        }
+
+        function startLaunchAnimation() {
+            launchFallbackTimer.stop();
+            if (opacity === 0 && !launchAnimation.running) {
+                launchAnimation.start();
+            }
+        }
+
+        // Fade in over the wallpaper rather than on a black screen while the wallpaper loads
+        Component.onCompleted: {
+            if (wallpaperLoaded) {
+                startLaunchAnimation();
+            } else {
+                launchFallbackTimer.start();
+            }
+        }
+        onWallpaperLoadedChanged: {
+            if (wallpaperLoaded) {
+                startLaunchAnimation();
+            }
+        }

         WallpaperFader {
             anchors.fill: parent
-- 
